1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Calculator</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body {
10	    margin: 0;
11	    min-height: 100vh;
12	    display: flex;
13	    align-items: center;
14	    justify-content: center;
15	    background: #eceef1;
16	    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
17	  }
18	  .calc {
19	    width: 320px;
20	    max-width: calc(100vw - 32px);
21	    background: #1f2227;
22	    border-radius: 20px;
23	    padding: 20px;
24	    box-shadow: 0 12px 32px rgba(0, 0, 0, 0.25);
25	  }
26	  .screen { position: relative; }
27	  .display {
28	    color: #fff;
29	    font-size: 44px;
30	    text-align: right;
31	    padding: 16px 8px 20px;
32	    min-height: 88px;
33	    overflow-x: auto;
34	    white-space: nowrap;
35	  }
36	  .keys {
37	    display: grid;
38	    grid-template-columns: repeat(4, 1fr);
39	    gap: 10px;
40	  }
41	  button {
42	    font: inherit;
43	    font-size: 22px;
44	    height: 60px;
45	    border: none;
46	    border-radius: 12px;
47	    background: #3a3e45;
48	    color: #fff;
49	    cursor: pointer;
50	  }
51	  button:active { filter: brightness(1.25); }
52	  button.op { background: #f59e0b; }
53	  button.clear { background: #9ca3af; color: #111; }
54	  button.wide { grid-column: span 2; }
55	  button.mem { height: 44px; font-size: 18px; background: #2c3036; color: #d1d5db; }
56	  .mem-indicator { position: absolute; top: 8px; left: 8px; font-size: 14px; font-weight: 600; color: #f59e0b; }
57	  .mem-indicator[data-active="false"] { opacity: 0.2; }
58	  .tape { margin-top: 16px; border-top: 1px solid #3a3e45; padding-top: 12px; }
59	  .tape-head { display: flex; justify-content: space-between; align-items: center; color: #9ca3af; font-size: 14px; }
60	  .tape-head button { font-size: 14px; height: 28px; padding: 0 12px; background: #3a3e45; }
61	  .tape-rows { max-height: 180px; overflow-y: auto; }
62	  .tape-row { display: flex; justify-content: space-between; gap: 12px; padding: 6px 0; font-size: 15px; }
63	  .tape-row + .tape-row { border-top: 1px solid #2c3036; }
64	  .tape-expr { color: #9ca3af; overflow-wrap: anywhere; }
65	  .tape-result { color: #fff; white-space: nowrap; }
66	</style>
67	</head>
68	<body>
69	<div class="calc">
70	  <div class="screen">
71	    <!-- [REQ-009] memory indicator, outside the display so its text stays the number -->
72	    <span class="mem-indicator" data-testid="mem-indicator" data-active="false">M</span>
73	    <div class="display" data-testid="calc-display" data-value="0" data-error="false">0</div>
74	  </div>
75	  <div class="keys">
76	    <!-- [REQ-009] memory keys -->
77	    <button class="mem" data-testid="key-mc">MC</button>
78	    <button class="mem" data-testid="key-mr">MR</button>
79	    <button class="mem wide" data-testid="key-mplus">M+</button>
80	    <button class="clear wide" data-testid="key-lparen">(</button>
81	    <button class="clear wide" data-testid="key-rparen">)</button>
82	    <!-- [REQ-006] no % key; AC takes its space -->
83	    <button class="clear wide" data-testid="key-clear">AC</button>
84	    <button class="clear" data-testid="key-sign">±</button>
85	    <button class="op" data-testid="key-div" data-op="/">÷</button>
86	    <button data-testid="key-7" data-digit="7">7</button>
87	    <button data-testid="key-8" data-digit="8">8</button>
88	    <button data-testid="key-9" data-digit="9">9</button>
89	    <button class="op" data-testid="key-mul" data-op="*">×</button>
90	    <button data-testid="key-4" data-digit="4">4</button>
91	    <button data-testid="key-5" data-digit="5">5</button>
92	    <button data-testid="key-6" data-digit="6">6</button>
93	    <button class="op" data-testid="key-sub" data-op="-">−</button>
94	    <button data-testid="key-1" data-digit="1">1</button>
95	    <button data-testid="key-2" data-digit="2">2</button>
96	    <button data-testid="key-3" data-digit="3">3</button>
97	    <button class="op" data-testid="key-add" data-op="+">+</button>
98	    <button class="wide" data-testid="key-0" data-digit="0">0</button>
99	    <button data-testid="key-dot">.</button>
100	    <button class="op" data-testid="key-equals">=</button>
101	  </div>
102	  <!-- [REQ-007] running tape of past calculations, newest first -->
103	  <div class="tape">
104	    <div class="tape-head">
105	      <span>History</span>
106	      <button data-testid="tape-clear">Clear</button>
107	    </div>
108	    <div class="tape-rows" data-testid="calc-tape"></div>
109	  </div>
110	</div>
111	<script>
112	  var displayEl = document.querySelector('[data-testid="calc-display"]');
113	  var tapeEl = document.querySelector('[data-testid="calc-tape"]');
114	  var OP_SYMBOLS = { '+': '+', '-': '−', '*': '×', '/': '÷' };
115	
116	  var memIndicatorEl = document.querySelector('[data-testid="mem-indicator"]');
117	
118	  var state;
119	  // [REQ-009] memory starts at zero, holds the exact value, and survives AC
120	  var memory = 0;
121	
122	  // [REQ-009] M+ adds the exact displayed value (never the rounded text); the entry is finished
123	  function memoryAdd() {
124	    memory += Number(state.entry);
125	    state.typing = false;
126	    render();
127	  }
128	
129	  // [REQ-009] MR puts the exact memory value in the display as a result, not typed text
130	  function memoryRecall() {
131	    state.entry = String(memory);
132	    state.entryExpr = null;
133	    state.fresh = false;
134	    state.typing = false;
135	    render();
136	  }
137	
138	  // [REQ-009] MC resets memory to zero; the display is left alone
139	  function memoryClear() {
140	    memory = 0;
141	    render();
142	  }
143	
144	  // [REQ-007] the entry as it reads in the expression: a closed group, or the number
145	  function entryText() {
146	    return state.entryExpr !== null ? state.entryExpr : formatNumber(Number(state.entry));
147	  }
148	
149	  // [REQ-007] add a tape row at the top; data-value holds String(value)
150	  function addTapeRow(expr, value) {
151	    var row = document.createElement('div');
152	    row.className = 'tape-row';
153	    row.setAttribute('data-testid', 'tape-row');
154	    var exprEl = document.createElement('span');
155	    exprEl.className = 'tape-expr';
156	    exprEl.setAttribute('data-testid', 'tape-expr');
157	    exprEl.textContent = expr;
158	    var resultEl = document.createElement('span');
159	    resultEl.className = 'tape-result';
160	    resultEl.setAttribute('data-testid', 'tape-result');
161	    resultEl.setAttribute('data-value', String(value));
162	    resultEl.textContent = formatNumber(value);
163	    row.appendChild(exprEl);
164	    row.appendChild(resultEl);
165	    tapeEl.insertBefore(row, tapeEl.firstChild);
166	  }
167	
168	  // [REQ-001] reset to the initial state: display 0, nothing pending
169	  // [REQ-003] clear also leaves the error state
170	  function clearAll() {
171	    state = { entry: '0', stored: null, op: null, fresh: true, typing: false, error: false, groups: [],
172	      tokens: [], entryExpr: null };
173	    render();
174	  }
175	
176	  // [REQ-001] apply an operator
177	  // [REQ-003] exact result, never rounded; division by zero returns null (error)
178	  function compute(a, op, b) {
179	    if (op === '+') return a + b;
180	    if (op === '-') return a - b;
181	    if (op === '*') return a * b;
182	    if (b === 0) return null;
183	    return a / b;
184	  }
185	
186	  // [REQ-003] presentation only: at most 10 significant digits, no trailing zeros,
187	  // exponential only when |n| >= 1e10 or |n| < 1e-9
188	  function formatNumber(n) {
189	    if (n === 0) return '0';
190	    if (!isFinite(n)) return String(n);
191	    var parts = n.toExponential(9).split('e');
192	    var exp = Number(parts[1]);
193	    if (exp >= 10 || exp < -9) {
194	      return parts[0].replace(/\.?0+$/, '') + 'e' + (exp >= 0 ? '+' : '') + exp;
195	    }
196	    var sign = n < 0 ? '-' : '';
197	    var digits = parts[0].replace('-', '').replace('.', '');
198	    var intPart, fracPart;
199	    if (exp >= 0) {
200	      intPart = digits.slice(0, exp + 1);
201	      fracPart = digits.slice(exp + 1);
202	    } else {
203	      intPart = '0';
204	      fracPart = new Array(-exp).join('0') + digits;
205	    }
206	    fracPart = fracPart.replace(/0+$/, '');
207	    return sign + intPart + (fracPart ? '.' + fracPart : '');
208	  }
209	
210	  // [REQ-003] enter the error state
211	  function setError() {
212	    state.error = true;
213	    render();
214	  }
215	
216	  // [REQ-001] digits build the entry
217	  // [REQ-004] a shown result (not typed) is replaced, not appended to
218	  // [REQ-007] a new number replaces a closed group in the expression
219	  function inputDigit(d) {
220	    state.entryExpr = null;
221	    if (state.fresh || !state.typing) {
222	      state.entry = d;
223	      state.fresh = false;
224	    } else {
225	      state.entry = state.entry === '0' ? d : state.entry + d;
226	    }
227	    state.typing = true;
228	    render();
229	  }
230	
231	  // [REQ-001] at most one decimal point per entry
232	  function inputDot() {
233	    state.entryExpr = null; // [REQ-007]
234	    if (state.fresh || !state.typing) {
235	      state.entry = '0.';
236	      state.fresh = false;
237	    } else if (state.entry.indexOf('.') === -1) {
238	      state.entry += '.';
239	    }
240	    state.typing = true;
241	    render();
242	  }
243	
244	  // [REQ-004] flip the sign of the current entry; a typed entry keeps its text
245	  // [REQ-007] flipping a closed group marks the group with −
246	  function inputSign() {
247	    if (state.entryExpr !== null) {
248	      state.entryExpr = state.entryExpr.charAt(0) === '−' ? state.entryExpr.slice(1) : '−' + state.entryExpr;
249	    }
250	    if (state.typing) {
251	      if (state.entry !== '0') {
252	        state.entry = state.entry.charAt(0) === '-' ? state.entry.slice(1) : '-' + state.entry;
253	      }
254	    } else {
255	      state.entry = String(-Number(state.entry) || 0);
256	      state.fresh = false;
257	    }
258	    render();
259	  }
260	
261	  // [REQ-001] store the operator; chains evaluate left to right
262	  // [REQ-002] immediate execution: an operator first applies the waiting op and shows the
263	  // running result; no precedence, so 2 + 3 × 4 = is 20
264	  // [REQ-007] record the entry and operator; a replaced operator replaces its token
265	  function inputOp(op) {
266	    var current = Number(state.entry);
267	    if (state.fresh && state.op !== null) {
268	      state.tokens[state.tokens.length - 1] = OP_SYMBOLS[op];
269	    } else {
270	      state.tokens.push(entryText(), OP_SYMBOLS[op]);
271	    }
272	    state.entryExpr = null;
273	    if (state.op !== null && !state.fresh) {
274	      var result = compute(state.stored, state.op, current);
275	      if (result === null) return setError();
276	      state.entry = String(result);
277	      state.stored = result;
278	    } else if (state.op === null) {
279	      state.stored = current;
280	    }
281	    state.op = op;
282	    state.fresh = true;
283	    state.typing = false;
284	    render();
285	  }
286	
287	  // [REQ-005] open a group: park the waiting stored value and op; the group starts empty
288	  // [REQ-007] the group remembers where its tokens start
289	  function openGroup() {
290	    state.groups.push({ stored: state.op === null ? null : state.stored, op: state.op, at: state.tokens.length });
291	    state.tokens.push('(');
292	    state.entryExpr = null;
293	    state.stored = null;
294	    state.op = null;
295	    state.fresh = true;
296	    state.typing = false;
297	    render();
298	  }
299	
300	  // [REQ-005] close the innermost group: its result becomes the entry for the outer op
301	  function closeGroup() {
302	    if (state.groups.length === 0) return;
303	    var value = Number(state.entry);
304	    if (state.op !== null) {
305	      value = compute(state.stored, state.op, value);
306	      if (value === null) return setError();
307	    }
308	    var outer = state.groups.pop();
309	    // [REQ-007] the whole group becomes the entry's text
310	    state.entryExpr = state.tokens.splice(outer.at).concat(entryText(), ')').join(' ');
311	    state.stored = outer.stored;
312	    state.op = outer.op;
313	    state.entry = String(value);
314	    state.fresh = false;
315	    state.typing = false;
316	    render();
317	  }
318	
319	  // [REQ-001] equals shows the result of stored op entry
320	  // [REQ-005] equals first closes any open groups
321	  // [REQ-007] a completed calculation adds a tape row
322	  function equals() {
323	    var closed = state.groups.length > 0;
324	    while (state.groups.length > 0) {
325	      closeGroup();
326	      if (state.error) return;
327	    }
328	    if (state.op === null) {
329	      if (closed) {
330	        addTapeRow(state.tokens.concat(entryText()).join(' '), Number(state.entry));
331	        state.tokens = [];
332	        state.entryExpr = null;
333	      }
334	      return;
335	    }
336	    var result = compute(state.stored, state.op, Number(state.entry));
337	    if (result === null) return setError();
338	    addTapeRow(state.tokens.concat(entryText()).join(' '), result);
339	    state.tokens = [];
340	    state.entryExpr = null;
341	    state.entry = String(result);
342	    state.stored = null;
343	    state.op = null;
344	    state.fresh = true;
345	    state.typing = false;
346	    render();
347	  }
348	
349	  // [REQ-001] data-value holds String(value)
350	  // [REQ-003] typed entry shown as typed; other numbers formatted at render time only;
351	  // data-value stays exact; data-error always present
352	  function render() {
353	    var value = Number(state.entry);
354	    if (state.error) {
355	      displayEl.textContent = 'Error';
356	      displayEl.setAttribute('data-value', 'NaN');
357	    } else {
358	      displayEl.textContent = state.typing ? state.entry : formatNumber(value);
359	      displayEl.setAttribute('data-value', String(value));
360	    }
361	    displayEl.setAttribute('data-error', state.error ? 'true' : 'false');
362	    // [REQ-009]
363	    memIndicatorEl.setAttribute('data-active', memory !== 0 ? 'true' : 'false');
364	  }
365	
366	  document.querySelector('.keys').addEventListener('click', function (e) {
367	    var btn = e.target.closest('button');
368	    if (!btn) return;
369	    var id = btn.getAttribute('data-testid');
370	    // [REQ-003] in the error state only clear works
371	    if (state.error && id !== 'key-clear') return;
372	    if (btn.hasAttribute('data-digit')) inputDigit(btn.getAttribute('data-digit'));
373	    else if (btn.hasAttribute('data-op')) inputOp(btn.getAttribute('data-op'));
374	    else if (id === 'key-dot') inputDot();
375	    else if (id === 'key-equals') equals();
376	    else if (id === 'key-sign') inputSign();
377	    else if (id === 'key-lparen') openGroup();
378	    else if (id === 'key-rparen') closeGroup();
379	    else if (id === 'key-clear') clearAll();
380	    else if (id === 'key-mplus') memoryAdd();
381	    else if (id === 'key-mr') memoryRecall();
382	    else if (id === 'key-mc') memoryClear();
383	  });
384	
385	  // [REQ-007] clearing the tape leaves the calculator and display alone
386	  document.querySelector('[data-testid="tape-clear"]').addEventListener('click', function () {
387	    tapeEl.textContent = '';
388	  });
389	
390	  clearAll();
391	</script>
392	</body>
393	</html>
