<script>
(function(){
var out=[];
function q(id){return document.querySelector('[data-testid="'+id+'"]');}
var names={'+':'add','-':'sub','*':'mul','/':'div','.':'dot','=':'equals','(':'lparen',')':'rparen','C':'clear','±':'sign','S':'sci','√':'sqrt','²':'square','r':'recip','M':'mplus','R':'mr','X':'mc'};
function tap(seq){seq.split(' ').forEach(function(k){if(!k)return;var id=/^\d$/.test(k)?'key-'+k:'key-'+names[k];var b=q(id);if(!b)throw id;b.click();});}
function key(seq){seq.split(' ').forEach(function(k){document.dispatchEvent(new KeyboardEvent('keydown',{key:k,bubbles:true,cancelable:true}));});}
function disp(){return q('calc-display').textContent;}
function t(name,fn,exp){tap('C');var got;try{got=fn();}catch(e){got='THROW '+e;}out.push((String(got)===String(exp)?'PASS ':'FAIL ')+name+' got='+got+' exp='+exp);}
t('add',function(){tap('1 2 + 7 =');return disp();},'19');
t('precedence none',function(){tap('2 + 3 * 4 =');return disp();},'20');
t('running result',function(){tap('2 + 3 *');return disp();},'5');
t('0.1+0.2',function(){tap('. 1 + . 2 =');return disp();},'0.3');
t('1/3',function(){tap('1 / 3 =');return disp()+'|'+q('calc-display').dataset.value;},'0.3333333333|'+String(1/3));
t('div0',function(){tap('5 / 0 =');return disp()+q('calc-display').dataset.error;},'Errortrue');
t('error locks',function(){tap('5 / 0 = 7');return disp();},'Error');
t('clear error',function(){tap('5 / 0 = C');return disp();},'0');
t('one dot',function(){tap('1 . . 5');return disp();},'1.5');
t('sign',function(){tap('5 ±');return disp();},'-5');
t('result replaced',function(){tap('2 + 2 = 7');return disp();},'7');
t('groups',function(){tap('2 * ( 3 + 4 ) =');return disp();},'14');
